function downloadProjectGeoJSON() {
  const meta=document.getElementById('exportMeta');
  if(presentedExport){meta.textContent='GeoJSON export declined: the wider-fleet view owns this table. Select a main pipeline technology first.';return;}
  try {
    const data=projectGeoJSON(filtered.map(index=>({...project(index),capacity_unit:UNITS[project(index).technology]})),{release:'{GEN}',source:registry.source,filters:Object.fromEntries(new URL(location.href).searchParams)});
    const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/geo+json'}));
    const anchor=document.createElement('a');anchor.href=url;anchor.download='pipeline-{GEN}-filtered.geojson';document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
    meta.textContent=data.metadata.records.toLocaleString('en-GB')+' filtered records exported as GeoJSON; '+data.metadata.null_geometry+' retain null geometry.';
  } catch(error){meta.textContent='GeoJSON export failed: '+error.message;}
}

